#!/usr/bin/env bash
# Vercel build for @status-im/community-dapp.
# Runs from the app dir (vercel root directory = apps/community-dapp).
set -euo pipefail

# Kept in sync with the foundry-toolchain version in .github/workflows/ci.yml.
FOUNDRY_VERSION=v1.5.1
FOUNDRY_SHA256=73640b01bd9ed29fdb4965085099371f8cf0dbbec3e2086cf54564efc4dcfe88

# Contract ABIs are generated by `forge build` and gitignored, so they must be
# built here. Fetch the contracts' submodules and install forge first.
git -C ../../ submodule update --init --recursive packages/community-contracts/lib

# Only forge is extracted: foundryup aborts because anvil needs GLIBC_2.35,
# newer than the build image provides.
FOUNDRY_TARBALL="foundry_${FOUNDRY_VERSION}_linux_amd64.tar.gz"
FOUNDRY_BIN_DIR="$HOME/.foundry/bin"
mkdir -p "$FOUNDRY_BIN_DIR"
curl -fsSL -o "/tmp/$FOUNDRY_TARBALL" \
  "https://github.com/foundry-rs/foundry/releases/download/$FOUNDRY_VERSION/$FOUNDRY_TARBALL"
echo "$FOUNDRY_SHA256  /tmp/$FOUNDRY_TARBALL" | sha256sum -c -
tar -xzf "/tmp/$FOUNDRY_TARBALL" -C "$FOUNDRY_BIN_DIR" forge
export PATH="$FOUNDRY_BIN_DIR:$PATH"
forge --version

pnpm --filter @status-im/community-contracts run build
pnpm --filter @status-im/js run build
pnpm --filter @status-im/community-dapp run generate:proto

NODE_OPTIONS=--openssl-legacy-provider pnpm exec webpack --mode=production
